impl LLMOrchestrator {
    pub async fn new() -> Result<Self> {
        let mut providers: HashMap<String, Box<dyn LLMProvider>> = HashMap::new();

        // Initialize all LLM providers
        providers.insert("gpt5".to_string(), Box::new(GPT5Provider::new().await?));
        providers.insert("gemini2.5".to_string(), Box::new(GeminiProvider::new().await?));
        providers.insert("grok4".to_string(), Box::new(GrokProvider::new().await?));
        providers.insert("llama4".to_string(), Box::new(LlamaProvider::new().await?));
        providers.insert("cerebras_gpt".to_string(), Box::new(CerebrasGPTProvider::new().await?));
        providers.insert("cerebras_qwen".to_string(), Box::new(CerebrasQwenProvider::new().await?));

        Ok(Self {
            providers,
            config: LLMConfig::default(),
        })
    }

    pub async fn consensus_analysis(&self, threat_data: &SecurityEvent) -> Result<ConsensusResult> {
        let mut responses = Vec::new();
        let analysis_prompt = self.build_analysis_prompt(threat_data);

        // Run analysis on all available models in parallel
        let futures: Vec<_> = self.providers.values()
            .map(|provider| provider.analyze(&analysis_prompt, &SecurityContext::from(threat_data)))
            .collect();

        let results = futures::future::join_all(futures).await;

        for result in results {
            if let Ok(response) = result {
                responses.push(response);
            }
        }

        // Apply consensus algorithm
        self.calculate_consensus(responses).await
    }
}

