    async fn websocket_handler(&self, ws: WebSocketUpgrade) -> impl IntoResponse {
        ws.on_upgrade(|socket| self.handle_websocket(socket))
    }

    async fn handle_websocket(&self, socket: WebSocket) {
        let (sender, mut receiver) = socket.split();
        let sender = Arc::new(Mutex::new(sender));

        // Start real-time metrics streaming
        let metrics_stream = self.start_metrics_stream(sender.clone());
        let threat_stream = self.start_threat_stream(sender.clone());
        let compliance_stream = self.start_compliance_stream(sender.clone());

        tokio::select! {
            _ = metrics_stream => {},
            _ = threat_stream => {},
            _ = compliance_stream => {},
            _ = receiver.next() => {},
        }
    }
}
