#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct APIKeyRecord {
    pub key_id: String,
    pub hashed_key: String,
    pub user_id: String,
    pub permissions: Vec<Permission>,
    pub rate_limits: RateLimitConfig,
    pub created_at: DateTime<Utc>,
    pub last_used: Option<DateTime<Utc>>,
    pub expires_at: Option<DateTime<Utc>>,
    pub is_active: bool,
    pub usage_metrics: UsageMetrics,
    pub security_level: SecurityLevel,
}

impl EnterpriseAPIKeyManager {
    pub async fn generate_enterprise_api_key(&self, request: APIKeyGenerationRequest) -> Result<GeneratedAPIKey> {
        // Step 1: Validate user permissions
        let user_permissions = self.authentication_service.get_user_permissions(&request.user_id).await?;
        if !user_permissions.can_generate_api_keys {
            return Err(anyhow!("Insufficient permissions to generate API key"));
        }

        // Step 2: Generate cryptographically secure API key
        let raw_key = self.generate_secure_key(256).await?;
        let key_id = Uuid::new_v4().to_string();
        let hashed_key = self.encryption_service.hash_api_key(&raw_key).await?;

        // Step 3: Create key record with enterprise features
        let api_key_record = APIKeyRecord {
            key_id: key_id.clone(),
            hashed_key,
            user_id: request.user_id.clone(),
            permissions: request.permissions.clone(),
            rate_limits: RateLimitConfig {
                requests_per_minute: request.rate_limit.unwrap_or(1000),
                requests_per_hour: request.hourly_limit.unwrap_or(10000),
                requests_per_day: request.daily_limit.unwrap_or(100000),
                burst_limit: request.burst_limit.unwrap_or(5000),
            },
            created_at: Utc::now(),
            last_used: None,
            expires_at: request.expires_at,
            is_active: true,
            usage_metrics: UsageMetrics::new(),
            security_level: request.security_level.unwrap_or(SecurityLevel::Enterprise),
        };

        // Step 4: Store in database with backup to GCP
        self.store_api_key_record(&api_key_record).await?;
        self.backup_to_gcp(&api_key_record).await?;

        // Step 5: Initialize rate limiter
        let rate_limiter = TokenBucket::new(
            api_key_record.rate_limits.requests_per_minute,
            api_key_record.rate_limits.burst_limit,
        );
        self.rate_limiters.write().await.insert(key_id.clone(), rate_limiter);

        // Step 6: Log for audit
        self.audit_logger.log_key_generation(&api_key_record, &request.user_id).await?;

        Ok(GeneratedAPIKey {
            key_id,
            api_key: raw_key,
            permissions: api_key_record.permissions,
            rate_limits: api_key_record.rate_limits,
            security_level: api_key_record.security_level,
        })
    }

    pub async fn authenticate_api_request(&self, request: &APIRequest) -> Result<AuthenticationResult> {
        let api_key = request.headers.get("X-API-Key")
            .ok_or_else(|| anyhow!("Missing API key"))?;

        // Step 1: Hash the provided key for lookup
        let hashed_key = self.encryption_service.hash_api_key(api_key).await?;

        // Step 2: Find key record
        let key_record = self.find_key_by_hash(&hashed_key).await?
            .ok_or_else(|| anyhow!("Invalid API key"))?;

        // Step 3: Validate key status
        if !key_record.is_active {
            return Ok(AuthenticationResult::Rejected("API key is inactive".to_string()));
        }

        if let Some(expires_at) = key_record.expires_at {
            if Utc::now() > expires_at {
                return Ok(AuthenticationResult::Rejected("API key has expired".to_string()));
            }
        }

        // Step 4: Check rate limits
        let rate_limit_result = self.check_rate_limits(&key_record.key_id).await?;
        if !rate_limit_result.allowed {
            return Ok(AuthenticationResult::RateLimited {
                retry_after: rate_limit_result.retry_after,
                limit_type: rate_limit_result.limit_type,
            });
        }

        // Step 5: Validate permissions for the requested endpoint
        let permission_check = self.validate_permissions(&key_record, request).await?;
        if !permission_check.allowed {
            return Ok(AuthenticationResult::Forbidden(permission_check.reason));
        }

        // Step 6: Update usage metrics
        self.update_usage_metrics(&key_record.key_id, request).await?;

        Ok(AuthenticationResult::Authenticated {
            key_id: key_record.key_id,
            user_id: key_record.user_id,
            permissions: key_record.permissions,
            security_level: key_record.security_level,
        })
    }

    async fn backup_to_gcp(&self, key_record: &APIKeyRecord) -> Result<()> {
        let backup_data = serde_json::to_string(key_record)?;
        let encrypted_backup = self.gcp_service_account.encrypt_data(&backup_data).await?;

        self.gcp_service_account
            .store_in_secret_manager(&key_record.key_id, &encrypted_backup)
            .await?;

        Ok(())
    }
}

