// frontend/src/components/Quantum/QuantumVisualization.tsx - QUANTUM FIELD VISUALIZATION
import React, { useEffect, useRef, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Text, Sphere, Line } from '@react-three/drei';
import * as THREE from 'three';
import { motion } from 'framer-motion-3d';

interface QuantumFieldProps {
  entanglementData: EntanglementData[];
  coherenceLevel: number;
}

const QuantumField: React.FC<QuantumFieldProps> = ({ entanglementData, coherenceLevel }) => {
  const meshRef = useRef<THREE.Mesh>(null);
  const particlesRef = useRef<THREE.Points>(null);

  const [particles, setParticles] = useState<Float32Array>();
  const [colors, setColors] = useState<Float32Array>();

  useEffect(() => {
    // Generate quantum particles
    const particleCount = 10000;
    const positions = new Float32Array(particleCount * 3);
    const colors = new Float32Array(particleCount * 3);

    for (let i = 0; i < particleCount; i++) {
      // Quantum field distribution
      const phi = Math.random() * Math.PI * 2;
      const theta = Math.acos(2 * Math.random() - 1);
      const radius = Math.pow(Math.random(), 0.33) * 10;

      positions[i * 3] = radius * Math.sin(theta) * Math.cos(phi);
      positions[i * 3 + 1] = radius * Math.sin(theta) * Math.sin(phi);
      positions[i * 3 + 2] = radius * Math.cos(theta);

      // Quantum state colors
      const quantumState = Math.random();
      if (quantumState < 0.33) {
        colors[i * 3] = 0; colors[i * 3 + 1] = 1; colors[i * 3 + 2] = 1; // Cyan
      } else if (quantumState < 0.66) {
        colors[i * 3] = 1; colors[i * 3 + 1] = 0; colors[i * 3 + 2] = 1; // Magenta
      } else {
        colors[i * 3] = 1; colors[i * 3 + 1] = 1; colors[i * 3 + 2] = 0; // Yellow
      }
    }

    setParticles(positions);
    setColors(colors);
  }, [entanglementData]);

  useFrame((state) => {
    if (meshRef.current) {
      meshRef.current.rotation.x = Math.sin(state.clock.elapsedTime * 0.5) * 0.1;
      meshRef.current.rotation.y += 0.01;
    }

    if (particlesRef.current) {
      particlesRef.current.rotation.y += 0.002;

      // Quantum coherence effects
      const material = particlesRef.current.material as THREE.PointsMaterial;
      material.opacity = 0.3 + coherenceLevel * 0.7;
    }
  });

  return (
    <group>
      {/* Quantum Particles */}
      <points ref={particlesRef}>
        <bufferGeometry>
          <bufferAttribute
            attach="attributes-position"
            count={particles?.length ? particles.length / 3 : 0}
            array={particles}
            itemSize={3}
          />
          <bufferAttribute
            attach="attributes-color"
            count={colors?.length ? colors.length / 3 : 0}
            array={colors}
            itemSize={3}
          />
        </bufferGeometry>
        <pointsMaterial
          size={0.05}
          vertexColors
          transparent
          opacity={0.8}
          sizeAttenuation
        />
      </points>

      {/* Entanglement Connections */}
      {entanglementData.map((entanglement, index) => (
        <Line
          key={index}
          points={[entanglement.particle1.position, entanglement.particle2.position]}
          color={`hsl(${180 + entanglement.strength * 180}, 100%, 50%)`}
          lineWidth={entanglement.strength * 2}
          transparent
          opacity={entanglement.strength}
        />
      ))}

      {/* Central Quantum Core */}
      <motion.mesh
        ref={meshRef}
        animate={{
          scale: [1, 1.2, 1],
          rotateY: [0, Math.PI * 2],
        }}
        transition={{
          duration: 4,
          repeat: Infinity,
          ease: "easeInOut",
        }}
      >
        <icosahedronGeometry args={[2, 2]} />
        <meshStandardMaterial
          color="#00ffff"
          transparent
          opacity={0.3}
          wireframe
        />
      </motion.mesh>

      {/* Quantum State Labels */}
      <Text
        position={[0, 5, 0]}
        fontSize={0.5}
        color="#ffffff"
        anchorX="center"
        anchorY="middle"
      >
        Quantum Coherence: {(coherenceLevel * 100).toFixed(1)}%
      </Text>
    </group>
  );
};

export const QuantumVisualization: React.FC = () => {
  const [entanglementData, setEntanglementData] = useState<EntanglementData[]>([]);
  const [coherenceLevel, setCoherenceLevel] = useState(0.85);

  useEffect(() => {
    // Simulate quantum entanglement data
    const generateEntanglementData = () => {
      const data: EntanglementData[] = [];
      for (let i = 0; i < 50; i++) {
        data.push({
          particle1: {
            position: new THREE.Vector3(
              (Math.random() - 0.5) * 20,
              (Math.random() - 0.5) * 20,
              (Math.random() - 0.5) * 20
            ),
          },
          particle2: {
            position: new THREE.Vector3(
              (Math.random() - 0.5) * 20,
              (Math.random() - 0.5) * 20,
              (Math.random() - 0.5) * 20
            ),
          },
          strength: Math.random(),
        });
      }
      setEntanglementData(data);
    };

    generateEntanglementData();
    const interval = setInterval(generateEntanglementData, 2000);

    return () => clearInterval(interval);
  }, []);

  return (
    <div style={{ width: '100%', height: '100vh', background: '#000' }}>
      <Canvas camera={{ position: [0, 0, 15], fov: 75 }}>
        <ambientLight intensity={0.2} />
        <pointLight position={[10, 10, 10]} intensity={1} />
        <pointLight position={[-10, -10, -10]} intensity={0.5} color="#ff00ff" />

        <QuantumField 
          entanglementData={entanglementData}
          coherenceLevel={coherenceLevel}
