async fn health_check(State(state): State<Arc<AppState>>) -> Json<serde_json::Value> {
    let health = state.get_health_status().await;
    Json(serde_json::json!({
        "status": "healthy",
        "timestamp": chrono::Utc::now(),
        "version": env!("CARGO_PKG_VERSION"),
        "quantum_coherence": health.quantum_coherence,
        "llm_providers_active": health.active_llm_providers,
        "database_status": health.database_status,
        "redis_status": health.redis_status
    }))
}

async fn metrics_endpoint(State(state): State<Arc<AppState>>) -> String {
    state.service_registry.metrics_collector.export_prometheus().await
}

async fn websocket_handler(
    ws: axum::extract::WebSocketUpgrade,
    State(state): State<Arc<AppState>>,
) -> axum::response::Response {
    ws.on_upgrade(move |socket| {
        state.service_registry.websocket_manager.handle_connection(socket)
    })
}

async fn auth_middleware(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    mut request: axum::extract::Request,
    next: axum::middleware::Next,
) -> Result<axum::response::Response, StatusCode> {
    // Extract API key or JWT token
    let auth_header = headers.get("authorization")
        .or_else(|| headers.get("x-api-key"))
        .and_then(|h| h.to_str().ok());

    if let Some(auth_value) = auth_header {
        match state.service_registry.auth_service.authenticate(auth_value).await {
            Ok(user) => {
                request.extensions_mut().insert(user);
                Ok(next.run(request).await)
            }
            Err(_) => Err(StatusCode::UNAUTHORIZED),
        }
    } else {
        // Allow health check and metrics without auth
        let path = request.uri().path();
        if path == "/health" || path == "/metrics" {
            Ok(next.run(request).await)
        } else {
            Err(StatusCode::UNAUTHORIZED)
        }
    }
}

async fn start_background_services(state: Arc<AppState>) -> Result<()> {
    info!("🔄 Starting background services");

    // Start quantum processing loop
    let quantum_state = state.clone();
    tokio::spawn(async move {
        loop {
            if let Err(e) = quantum_state.service_registry.quantum_processor.process_pending_requests().await {
                error!("Quantum processing error: {}", e);
            }
            tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
        }
    });

    // Start LLM health monitoring
    let llm_state = state.clone();
    tokio::spawn(async move {
        loop {
            if let Err(e) = llm_state.service_registry.llm_orchestrator.health_check_all().await {
                warn!("LLM health check failed: {}", e);
            }
            tokio::time::sleep(tokio::time::Duration::from_secs(30)).await;
        }
    });

    // Start security monitoring
    let security_state = state.clone();
    tokio::spawn(async move {
        loop {
            if let Err(e) = security_state.service_registry.security_manager.scan_for_threats().await {
                error!("Security scan error: {}", e);
            }
            tokio::time::sleep(tokio::time::Duration::from_secs(10)).await;
        }
    });

    // Start metrics collection
    let metrics_state = state.clone();
    tokio::spawn(async move {
        loop {
            if let Err(e) = metrics_state.service_registry.metrics_collector.collect_system_metrics().await {
                error!("Metrics collection error: {}", e);
            }
            tokio::time::sleep(tokio::time::Duration::from_secs(5)).await;
        }
    });

    Ok(())
}

async fn start_metrics_server(state: Arc<AppState>) -> Result<()> {
    let metrics_app = Router::new()
        .route("/metrics", get(move |State(state): State<Arc<AppState>>| async move {
            state.service_registry.metrics_collector.export_prometheus().await
        }))
        .with_state(state);

    let listener = tokio::net::TcpListener::bind("0.0.0.0:9090").await?;
    info!("📊 Metrics server listening on 0.0.0.0:9090");

    axum::serve(listener, metrics_app).await?;
    Ok(())
}
